package io.github.diodeme.ji.host;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import io.github.diodeme.ji.error.ErrorCode;
import io.github.diodeme.ji.error.JiException;
import java.util.List;
import org.junit.jupiter.api.Test;

final class FollowUpQueueTest {
    @Test
    void maintainsAcceptedAuditOrderWhileReorderingExecution() {
        var first = item("one", "command-1", 1, 0);
