        assertEquals(List.of(0, 1), reordered.items().stream().map(FollowUpQueue.Item::order).toList());
        JiException conflict = assertThrows(
                JiException.class, () -> queue.reorder(List.of("two", "one"), 1));
        assertEquals(ErrorCode.QUEUE_REVISION_CONFLICT, conflict.error().code());
    }

    @Test
    void steerPromotionIsIrreversibleAndConsumptionIsBoundedToOne() {
        var queue = FollowUpQueue.empty().enqueue(item("one", "command-1", 1, 0), 0)
                .enqueue(item("two", "command-2", 2, 1), 1)
                .promote("two", 2).promote("one", 3);
        FollowUpQueue.Consumed consumed = queue.consumeSteer(4);
        assertEquals("two", consumed.item().orElseThrow().itemId());
        assertEquals(1, consumed.queue().items().size());
        assertThrows(IllegalStateException.class, () -> queue.promote("one", 4));
    }

    @Test
    void preInjectionFailureRollsSteerToFrontButPostInjectionFailureDoesNot() {
        var original = item("one", "command-1", 1, 0);
        var queue = FollowUpQueue.empty().enqueue(original, 0).promote("one", 1);
        var consumed = queue.consumeSteer(2);
        var rolledBack = consumed.queue().rollbackUninjectedSteer(consumed.item().orElseThrow(), 3);
        assertEquals("one", rolledBack.items().getFirst().itemId());
        assertEquals(FollowUpQueue.Kind.FOLLOW_UP, rolledBack.items().getFirst().kind());
        assertTrue(consumed.queue().items().isEmpty());
    }

    @Test
    void abortPausesQueueAndRetrieveReturnsDraftOnlyToRequestingClient() {
        var queue = FollowUpQueue.empty().enqueue(item("one", "command-1", 1, 0), 0).pause(1);
        assertTrue(queue.consumeSteer(2).item().isEmpty());
        var removed = queue.remove("one", "phone", 2);
        assertEquals("phone", removed.draft().clientId());
        assertEquals(List.of("prompt-one"), removed.draft().content());
        assertEquals(3, removed.queue().revision());
        JiException conflict = assertThrows(JiException.class, () -> removed.queue().resume(2));
        assertEquals(ErrorCode.QUEUE_REVISION_CONFLICT, conflict.error().code());
        assertTrue(!removed.queue().resume(3).paused());
    }

    private static FollowUpQueue.Item item(String id, String commandId, long acceptedSeq, int order) {
        return new FollowUpQueue.Item(id, commandId, acceptedSeq, order, FollowUpQueue.Kind.FOLLOW_UP,
                "desktop", List.of("prompt-" + id), List.of());
    }
}
